import { getEditorMigration } from '@wix/ambassador-headless-editor-migrations-v1-editor-migration/http';
import { CliError, CliErrorCode } from '@wix/cli-error';
import type { HttpClient } from '@wix/cli-http-client';
import { getEditorMigrationResponseSchema } from './schemas.js';

export class EditorMigrationClient {
  constructor(private readonly httpClient: HttpClient) {}

  // HTTP errors are rethrown as-is: callers decide what a failed lookup means.
  getEditorMigration = async () => {
    const { data } = await this.httpClient.request(getEditorMigration({}));

    const response = getEditorMigrationResponseSchema.safeParse(data);
    if (!response.success) {
      throw new CliError({
        code: CliErrorCode.FailedToGetEditorMigration(),
        cause: response.error,
      });
    }

    return response.data;
  };
}
