import { z } from 'zod';

// Only the fields finalize-migration reads. Everything is optional so a
// missing value surfaces as a readable mismatch instead of a parse failure.
const editorMigrationSchema = z.object({
  phase: z.string().optional(),
  acceptedAction: z.string().optional(),
  parentMetaSiteId: z.string().optional(),
  parentCompanionAppId: z.string().nullish(),
});

export const getEditorMigrationResponseSchema = z.object({
  migration: editorMigrationSchema.optional(),
});

export type GetEditorMigrationResponse = z.infer<
  typeof getEditorMigrationResponseSchema
>;
