import { z } from 'zod';
import { isHttpError } from '@wix/cli-http-client';
import { CliError, CliErrorCode } from '@wix/cli-error';
import {
  EditorMigrationAction,
  EditorMigrationPhase,
} from '@wix/editor-migration-client';
import type {
  EditorMigrationClient,
  GetEditorMigrationResponse,
} from '@wix/editor-migration-client';
import { readEnv } from '../files/env.js';

const parentTargetSchema = z.object({
  appId: z.string().uuid(),
  siteId: z.string().uuid(),
});
export type ParentTarget = z.infer<typeof parentTargetSchema>;

function parseParentTarget(target: {
  appId?: string;
  siteId?: string;
}): ParentTarget {
  const parent = parentTargetSchema.safeParse(target);
  if (!parent.success) {
    throw new CliError({
      code: CliErrorCode.InvalidEditorMigrationTarget(target),
      cause: null,
    });
  }
  return parent.data;
}

export function parseOperatorTarget(flags: {
  appId?: string;
  siteId?: string;
}): ParentTarget | undefined {
  if (flags.appId === undefined && flags.siteId === undefined) {
    return;
  }
  return parseParentTarget({ appId: flags.appId, siteId: flags.siteId });
}

export async function readEnvTarget(projectFolder: string) {
  const env = await readEnv(projectFolder);
  return parseParentTarget({
    appId: env.WIX_CLIENT_ID,
    siteId: env.EDITOR_MIGRATION_PARENT_SITE_ID,
  });
}

export async function resolveParentDeploymentTarget(
  editorMigrationClient: EditorMigrationClient,
  expected: ParentTarget,
  operatorTarget?: ParentTarget
): Promise<{ target: ParentTarget; isAlreadyFinalized: boolean }> {
  let response: GetEditorMigrationResponse;
  try {
    response = await editorMigrationClient.getEditorMigration();
  } catch (cause) {
    if (!isHttpError(cause)) {
      throw cause;
    }
    if (operatorTarget) {
      return { target: operatorTarget, isAlreadyFinalized: false };
    }
    throw new CliError({
      code: CliErrorCode.EditorMigrationLookupFailed(expected),
      cause,
    });
  }

  const { migration } = response;
  if (!migration) {
    throw new CliError({
      code: CliErrorCode.EditorMigrationNotFound({ siteId: expected.siteId }),
      cause: null,
    });
  }

  const isAccepted =
    migration.acceptedAction === EditorMigrationAction.FINALIZE_MIGRATION &&
    (migration.phase === EditorMigrationPhase.MIGRATION_FINALIZING ||
      migration.phase === EditorMigrationPhase.COMPLETED);
  if (!isAccepted) {
    throw new CliError({
      code: CliErrorCode.EditorMigrationFinalizeNotAccepted(),
      cause: null,
      info: {
        phase: migration.phase,
        acceptedAction: migration.acceptedAction,
      },
    });
  }

  if (
    migration.parentMetaSiteId !== expected.siteId ||
    migration.parentCompanionAppId !== expected.appId
  ) {
    throw new CliError({
      code: CliErrorCode.EditorMigrationParentMismatch({
        expected,
        found: {
          appId: migration.parentCompanionAppId,
          siteId: migration.parentMetaSiteId,
        },
      }),
      cause: null,
    });
  }

  return {
    target: expected,
    isAlreadyFinalized: migration.phase === EditorMigrationPhase.COMPLETED,
  };
}
